var reverseString = function(s) {
    let left = 0;
    let right = s.length - 1;

    while (left < right) {
        // Swap the characters at both ends
        const temp = s[left];
        s[left] = s[right];
        s[right] = temp;

        // Move both pointers toward the center
        left = left + 1;
        right = right - 1;
    }
};
